es":[{"japanese":"一緒に行きましょう。","translation":"Let's go together."}],"collocations":["一緒に行く","一緒に勉強する"],"relatedWords":["友達"],"antonyms":[],"notes":"一緒に is the common form before an action: together with someone."},{"id":"vocab-tokidoki","slug":"tokidoki","title":"時々","jlptLevel":"N5","category":"vocabulary","subcategory":"adverbs","difficulty":2,"prerequisiteIds":[],"tags":["routine","time"],"writtenForm":"時々","reading":"ときどき","meanings":["sometimes"],"partOfSpeech":"adverb","commonness":5,"exampleSentences":[{"japanese":"時々、本を読みます。","translation":"I sometimes read books."}],"collocations":["時々行く","時々見る"],"relatedWords":["毎日"],"antonyms":[],"notes":"時々 usually comes before the action it modifies."},{"id":"vocab-yukkuri","slug":"yukkuri","title":"ゆっくり","jlptLevel":"N5","category":"vocabulary","subcategory":"adverbs","difficulty":2,"prerequisiteIds":["grammar-te-kudasai"],"tags":["conversation","adverb"],"writtenForm":"ゆっくり","reading":"ゆっくり","meanings":["slowly","at ease"],"partOfSpeech":"adverb","commonness":5,"exampleSentences":[{"japanese":"ゆっくり話してください。","translation":"Please speak slowly."}],"collocations":["ゆっくり話す","ゆっくり休む"],"relatedWords":["早い"],"antonyms":[],"notes":"ゆっくり is useful when asking for a slower pace in conversation."}],"kanji":[{"id":"kanji-hito","slug":"hito","title":"人","jlptLevel":"N5","category":"kanji","subcategory":"people","difficulty":1,"prerequisiteIds":[],"tags":["people","numbers"],"character":"人","meanings":["person","people"],"onyomi":["ジン","ニン"],"kunyomi":["ひと"],"usefulWords":[{"word":"人","reading":"ひと","meaning":"person"},{"word":"一人","reading":"ひとり","meaning":"one person"},{"word":"二人","reading":"ふたり","meaning":"two people"}]},{"id":"kanji-na","slug":"na","title":"名","jlptLevel":"N5","category":"kanji","subcategory":"people","difficulty":2,"prerequisiteIds":[],"tags":["people","introduction"],"character":"名","meanings":["name","fame"],"onyomi":["メイ","ミョウ"],"kunyomi":["な"],"usefulWords":[{"word":"名前","reading":"なまえ","meaning":"name"},{