i","subcategory":"calendar","difficulty":2,"prerequisiteIds":[],"tags":["calendar","days"],"character":"曜","meanings":["weekday"],"onyomi":["ヨウ"],"kunyomi":[],"usefulWords":[{"word":"日曜日","reading":"にちようび","meaning":"Sunday"},{"word":"月曜日","reading":"げつようび","meaning":"Monday"}]},{"id":"kanji-nen","slug":"nen","title":"年","jlptLevel":"N5","category":"kanji","subcategory":"calendar","difficulty":1,"prerequisiteIds":[],"tags":["calendar","time"],"character":"年","meanings":["year"],"onyomi":["ネン"],"kunyomi":["とし"],"usefulWords":[{"word":"今年","reading":"ことし","meaning":"this year"},{"word":"一年","reading":"いちねん","meaning":"one year"}]},{"id":"kanji-kiku","slug":"kiku","title":"聞","jlptLevel":"N5","category":"kanji","subcategory":"conversation","difficulty":2,"prerequisiteIds":[],"tags":["conversation","study"],"character":"聞","meanings":["hear","listen","ask"],"onyomi":["ブン","モン"],"kunyomi":["きく"],"usefulWords":[{"word":"聞く","reading":"きく","meaning":"listen / ask"},{"word":"新聞","reading":"しんぶん","meaning":"newspaper"}]},{"id":"kanji-doku","slug":"doku","title":"読","jlptLevel":"N5","category":"kanji","subcategory":"study","difficulty":2,"prerequisiteIds":[],"tags":["study","media"],"character":"読","meanings":["read"],"onyomi":["ドク","トク"],"kunyomi":["よむ"],"usefulWords":[{"word":"読む","reading":"よむ","meaning":"to read"},{"word":"読書","reading":"どくしょ","meaning":"reading books"}]},{"id":"kanji-sho","slug":"sho","title":"書","jlptLevel":"N5","category":"kanji","subcategory":"study","difficulty":2,"prerequisiteIds":[],"tags":["study","writing"],"character":"書","meanings":["write","book"],"onyomi":["ショ"],"kunyomi":["かく"],"usefulWords":[{"word":"書く","reading":"かく","meaning":"to write"},{"word":"図書館","reading":"としょかん","meaning":"library"}]},{"id":"kanji-kai","slug":"kai-meet","title":"会","jlptLevel":"N5","category":"kanji","subcategory":"people","difficulty":2,"prerequisiteIds":[],"tags":["people","plans"],"character":"会","meanings":["meet","meeting"],"onyomi":["カイ","エ"],"kunyomi":["あう"],"usefulWords":[{"word":"会う","reading":"あう","meaning":"to meet"},{"word":"会社","reading":"かいしゃ","meaning":"company"}]}],"grammar":[{"id":"grammar-mashou","slug":"mashou","title":"ましょう","jlptLevel":"N5","category":"grammar","subcategory":"invitations","difficulty":2,"prerequisiteIds":["grammar-masu"],"tags":["invitation","plans","conversation"],"pattern":"Vましょう","meaning":"let's do V; a polite suggestion","formation":"Verb stem + ましょう","intuition":"ましょう turns a plan into a suggestion for the speaker and listener together.","usageConditions":["Use it when suggesting a shared action.","It is more direct than ませんか and often follows an agreed plan."],"examples":[{"japanese":"一緒に行きましょう。","translation":"Let's go together."},{"japanese":"日曜日に会いましょう。","translation":"Let's meet on Sunday."}],"commonMistakes":["Use the verb stem before ましょう: 行きましょう, not 行くましょう.","ましょう includes the suggestion; do not add です after it."],"contrastIds":["contrast-masenka-mashou"],"practiceQuestionIds":[]},{"id":"grammar-masenka","slug":"masenka","title":"ませんか","jlptLevel":"N5","category":"grammar","subcategory":"invitations","difficulty":2,"prerequisiteIds":["grammar-masen"],"tags":["invitation","plans","conversation"],"pattern":"Vませんか","meaning":"would you like to V?; a soft invitation","formation":"Polite negative verb + か","intuition":"The negative question makes an invitation gentle and leaves room for the other person's choice.","usageConditions":["Use it to invite someone to do an action with you.","A positive response can use ましょう."],"examples":[{"japanese":"一緒に勉強しませんか。","translation":"Would you like to study together?"},{"japanese":"お茶を飲みませんか。","translation":"Would you like to drink tea?"}],"commonMistakes":["Do not use the dictionary form before か in this pattern.","This is an invitation, not simply a question about a negative action."],"contrastIds":["contrast-masenka-mashou"],"practiceQuestionIds":[]},{"id":"grammar-kara-made","slug":"kara-made","title":"から…まで","jlptLevel":"N5","category":"grammar","subcategory":"time and distance","difficulty":2,"prerequisiteIds":["grammar-kara"],"tags":["time","distance","routine"],"pattern":"Nから Nまで","meaning":"from N to N","formation":"Starting point + から + ending point + まで","intuition":"から marks where a range begins and まで marks where it ends.","usageConditions":["Use it for time ranges, places, and other clear endpoints.","Either endpoint can be omitted when the context is obvious."],"examples":[{"japanese":"九時から五時まで勉強します。","translation":"I study from nine to five."},{"japanese":"駅から大学まで電車で行きます。","translation":"I go by train from the station to the university."}],"commonMistakes":["Keep the order start から end まで.","まで marks the endpoint, not the means of transport."],"contrastIds":["contrast-kara-made"],"practiceQuestionIds":[]},{"id":"grammar-ya","slug":"ya","title":"や","jlptLevel":"N5","category":"grammar","subcategory":"listing","difficulty":2,"prerequisiteIds":["grammar-to"],"tags":["listing","objects","home"],"pattern":"NやN","meaning":"things like N and N","formation":"Noun + や + noun; often followed by など when the list is explicitly incomplete","intuition":"や gives examples from a larger group instead of presenting a complete list.","usageConditions":["Use it when naming representative items.","Use と for a complete list of the items you mean."],"examples":[{"japanese":"机の上に本やノートがあります。","translation":"There are books, notebooks, and things like that on the desk."},{"japanese":"日曜日は本や音楽を楽しみます。","translation":"On Sundays I enjoy books, music, and things like that."}],"commonMistakes":["や is not the usual particle for people you do something with.","The list with や is understood as incomplete."],"contrastIds":["contrast-ya-to"],"practiceQuestionIds":[]},{"id":"grammar-te-kudasai","slug":"te-kudasai","title":"てください","jlptLevel":"N5","category":"grammar","subcategory":"requests","difficulty":2,"prerequisiteIds":["grammar-te-form"],"tags":["request","conversation"],"pattern":"Vてください","meaning":"please do V","formation":"Verb て-form + ください","intuition":"ください makes a request for an action polite and clear.","usageConditions":["Use it for a direct but polite request.","The verb before ください must be in て-form."],"examples":[{"japanese":"名前を書いてください。","translation":"Please write your name."},{"japanese":"ゆっくり話してください。","translation":"Please speak slowly."}],"commonMistakes":["Use て-form, not ます-form: 書いてください, not 書きますください.","ください is part of the request pattern, not a standalone verb ending here."],"contrastIds":["contrast-te-kudasai"],"practiceQuestionIds":[]},{"id":"grammar-adverb-totemo","slug":"totemo","title":"とても","jlptLevel":"N5","category":"grammar","subcategory":"adverbs","difficulty":1,"prerequisiteIds":[],"tags":["adverb","adjective","description"],"pattern":"とても + adjective","meaning":"very; greatly","formation":"Place とても before the adjective or adverb it strengthens.","intuition":"とても increases the intensity of a description without changing its grammar.","usageConditions":["Use it before an adjective or adverb.","It can describe a strong positive or negative degree."],"examples":[{"japanese":"この本はとても面白いです。","translation":"This book is very interesting."},{"japanese":"今日はとても暑いです。","translation":"It is very hot today."}],"commonMistakes":["Put とても before the description, not after です.","Do not confuse とても with ときどき, which describes frequency."],"contrastIds":[],"practiceQuestionIds":[]}],"grammarContrasts":[{"id":"contrast-masenka-mashou","title":"ませんか and ましょう","grammarPointIds":["grammar-masenka","grammar-mashou"],"explanation":"ませんか offers a gentle invitation and leaves the response open. ましょう presents a shared suggestion, often after both people are ready to agree.","examples":[{"japanese":"一緒に勉強しませんか。","translation":"Would you like to study together?"},{"japanese":"はい、勉強しましょう。","translation":"Yes, let's study."}],"exercises":["Invite someone softly with ませんか.","Turn an accepted plan into a shared suggestion with ましょう."]},{"id":"contrast-kara-made","title":"から and まで","grammarPointIds":["grammar-kara-made"],"explanation":"から marks the starting point of a range, while まで marks the endpoint. They commonly work as a pair for time and distance.","examples":[{"japanese":"九時から勉強します。","translation":"I study from nine."},{"japanese":"九時から五時まで勉強します。","translation":"I study from nine to five."}],"exercises":["Mark the start of a schedule with から.","Add the end of the schedule with まで."]},{"id":"contrast-ya-to","title":"や and と","grammarPointIds":["grammar-ya","grammar-to"],"explanation":"と presents a complete list or the person you act with. や gives representative examples from a larger, unfinished list.","examples":[{"japanese":"本とノートがあります。","translation":"There are a book and a notebook."},{"japanese":"本やノートがあります。","translation":"There are books, notebooks, and things like that."}],"exercises":["Use と when the list is complete.","Use や when the list gives examples."]},{"id":"contrast-te-kudasai","title":"て-form and てください","grammarPointIds":["grammar-te-form","grammar-te-kudasai"],"explanation":"The て-form connects actions or participates in other patterns. Adding ください turns it into a polite request.","examples":[{"japanese":"本を読んで、勉強します。","translation":"I read a book and then study."},{"japanese":"本を読んでください。","translation":"Please read the book."}],"exercises":["Use て-form to connect two actions.","Add ください when asking someone to do the action."]},{"id":"contrast-time-ranges","title":"午前 and 午後","grammarPointIds":["grammar-kara-made"],"explanation":"午前 places a clock time before noon, while 午後 places it after noon. Both can set the time for a routine.","examples":[{"japanese":"午前七時に起きます。","translation":"I get up at seven in the morning."},{"japanese":"午後三時に会います。","translation":"I meet someone at three in the afternoon."}],"exercises":["Use 午前 for a morning clock time.","Use 午後 for an afternoon clock time."]}],"readings":[{"id":"reading-self-introduction","slug":"self-introduction","title":"短い自己紹介","jlptLevel":"N5","category":"reading","subcategory":"short narrative","difficulty":2,"prerequisiteIds":["grammar-wa","grammar-masu"],"tags":["introduction","study","calendar"],"passage":"こんにちは。私は学生です。毎日、日本語を勉強します。日曜日は友達と会います。","translation":"Hello. I am a student. I study Japanese every day. On Sundays, I meet a friend.","vocabularyIds":["vocab-konnichiwa","vocab-watashi","vocab-gakusei","vocab-mainichi","vocab-nihongo","vocab-benkyou","vocab-nichiyoubi","vocab-tomodachi","vocab-au"],"grammarIds":["grammar-wa","grammar-masu","grammar-to"],"kanjiIds":["kanji-watashi","kanji-gaku","kanji-go-lang","kanji-you","kanji-kai"],"estimatedDifficulty":2,"questions":[{"prompt":"毎日、何を勉強しますか。","options":["英語","日本語","数学","音楽"],"correctAnswer":1,"questionType":"short passage detail","explanation":"毎日、日本語を勉強します。"},{"prompt":"日曜日にだれと会いますか。","options":["先生","家族","友達","学生"],"correctAnswer":2,"questionType":"information retrieval","explanation":"日曜日は友達と会います。"}]},{"id":"reading-weekday-schedule","slug":"weekday-schedule","title":"一日の予定","jlptLevel":"N5","category":"reading","subcategory":"practical schedule","difficulty":3,"prerequisiteIds":["grammar-ni","grammar-de","grammar-kara-made"],"tags":["time","routine","study"],"passage":"午前は大学へ行きます。午後は図書館で本を読みます。夜は家へ帰ります。日曜日は休みます。","translation":"In the morning I go to university. In the afternoon I read a book at the library. At night I return home. On Sunday I rest.","vocabularyIds":["vocab-gozen","vocab-gogo","vocab-daigaku","vocab-toshokan","vocab-hon","vocab-yomu","vocab-yoru","vocab-ie","vocab-kaeru","vocab-nichiyoubi","vocab-yasumu"],"grammarIds":["grammar-wa","grammar-ni","grammar-de","grammar-masu"],"kanjiIds":["kanji-go-noon","kanji-ji","kanji-doku","kanji-sho","kanji-you","kanji-kyuu"],"estimatedDifficulty":3,"questions":[{"prompt":"午後、どこで本を読みますか。","options":["大学","駅","図書館","家"],"correctAnswer":2,"questionType":"short passage detail","explanation":"午後は図書館で本を読みます。"},{"prompt":"日曜日は何をしますか。","options":["大学へ行きます","本を読みます","家へ帰ります","休みます"],"correctAnswer":3,"questionType":"information retrieval","explanation":"日曜日は休みます。"}]}],"listening":[{"id":"listening-invitation","slug":"invitation","title":"一緒に行きませんか","jlptLevel":"N5","category":"listening","subcategory":"invitation","difficulty":2,"prerequisiteIds":["grammar-masenka","grammar-mashou"],"tags":["plans","conversation","invitation"],"situation":"Two friends make a Sunday plan.","audioUrl":null,"voice":"ja-JP conversational TTS","speed":0.88,"sourceType":"tts","transcript":"A: 日曜日、一緒に図書館へ行きませんか。\nB: はい、行きましょう。\nA: 何時に会いますか。\nB: 午後二時に会いましょう。","questions":[{"prompt":"二人はいつ図書館へ行きますか。","answers":["土曜日","日曜日","月曜日","毎日"],"correctAnswer":1,"questionType":"key point","explanation":"日曜日、一緒に図書館へ行きませんか。"},{"prompt":"何時に会いますか。","answers":["午前二時","午後二時","午後三時","午後五時"],"correctAnswer":1,"questionType":"quick response","explanation":"午後二時に会いましょう。"}]},{"id":"listening-class-plan","slug":"class-plan","title":"午前と午後","jlptLevel":"N5","category":"listening","subcategory":"daily schedule","difficulty":3,"prerequisiteIds":["grammar-wa","grammar-masu","grammar-de"],"tags":["time","study","routine"],"situation":"A learner explains a simple day's schedule.","audioUrl":null,"voice":"ja-JP conversational TTS","speed":0.86,"sourceType":"tts","transcript":"A: 明日、何をしますか。\nB: 午前は大学へ行きます。午後は図書館で勉強します。\nA: 夜は？\nB: 家へ帰ります。","questions":[{"prompt":"午前、どこへ行きますか。","answers":["大学","図書館","駅","家"],"correctAnswer":0,"questionType":"key point","explanation":"午前は大学へ行きます。"},{"prompt":"午後、何をしますか。","answers":["休みます","勉強します","買います","会います"],"correctAnswer":1,"questionType":"task-based response","explanation":"午後は図書館で勉強します。"}]}]}$michi_payload$::jsonb;
begin
  select id, 'course-n5-foundations', slug, title, description, region, 3
  from jsonb_to_recordset(payload #> '{course,chapters}') as chapter(id text, slug text, title text, description text, region text) on conflict (id) do nothing;
  select lesson.id, 'chapter-conversation-and-plans', lesson.slug, lesson.title, lesson.subtitle, lesson.description, lesson."estimatedMinutes", 0
  from jsonb_array_elements(payload #> '{course,chapters}') as chapter(value)
  cross join lateral jsonb_to_recordset(chapter.value->'lessons') as lesson(id text, slug text, title text, subtitle text, description text, "estimatedMinutes" integer) on conflict (id) do nothing;
  select item.id, item.slug, item.category, item."jlptLevel", item.subcategory, item.difficulty, item."prerequisiteIds", item.tags
  from jsonb_to_recordset((payload->'vocabulary') || (payload->'kanji') || (payload->'grammar') || (payload->'readings') || (payload->'listening')) as item(id text, slug text, category text, subcategory text, difficulty integer, "jlptLevel" text, "prerequisiteIds" text[], tags text[]) on conflict (id) do nothing;
  select item.id, item."writtenForm", item.reading, item.meanings, item."partOfSpeech", item.commonness, item."exampleSentences", item.collocations, item."relatedWords", item.antonyms, item.notes
  from jsonb_to_recordset(payload->'vocabulary') as item(id text, "writtenForm" text, reading text, meanings text[], "partOfSpeech" text, commonness integer, "exampleSentences" jsonb, collocations text[], "relatedWords" text[], antonyms text[], notes text) on conflict (item_id) do nothing;
  select item.id, item.character, item.meanings, item.onyomi, item.kunyomi, item."strokeCount", item.grade, item.radical, coalesce(item.nanori, '{}'), coalesce(item.components, '{}'), item.mnemonic, item."strokeOrder", item."usefulWords"
  from jsonb_to_recordset(payload->'kanji') as item(id text, character text, meanings text[], onyomi text[], kunyomi text[], "strokeCount" integer, grade integer, radical text, nanori text[], components text[], mnemonic text, "strokeOrder" text, "usefulWords" jsonb) on conflict (item_id) do nothing;
  select item.id, item.pattern, item.meaning, item.formation, item.intuition, item."usageConditions", item.examples, item."commonMistakes", item."contrastIds", item."practiceQuestionIds"
  from jsonb_to_recordset(payload->'grammar') as item(id text, pattern text, meaning text, formation text, intuition text, "usageConditions" text[], examples jsonb, "commonMistakes" text[], "contrastIds" text[], "practiceQuestionIds" text[]) on conflict (item_id) do nothing;
  select item.id, item.title, item."grammarPointIds", item.explanation, item.examples, item.exercises
  from jsonb_to_recordset(payload->'grammarContrasts') as item(id text, title text, "grammarPointIds" text[], explanation text, examples jsonb, exercises text[]) on conflict (id) do nothing;
  select item.id, item.title, item.passage, item.translation, item."vocabularyIds", item."grammarIds", item."kanjiIds", item."estimatedDifficulty"
  from jsonb_to_recordset(payload->'readings') as item(id text, title text, passage text, translation text, "vocabularyIds" text[], "grammarIds" text[], "kanjiIds" text[], "estimatedDifficulty" integer) on conflict (item_id) do nothing;
  select item.id, item.title, item.situation, item."audioUrl", item.voice, item.speed, item."sourceType", item.transcript, item.questions
  from jsonb_to_recordset(payload->'listening') as item(id text, title text, situation text, "audioUrl" text, voice text, speed numeric, "sourceType" text, transcript text, questions jsonb) on conflict (item_id) do nothing;
  select lesson.id, item.item_id, item.sort_order::integer
  from jsonb_array_elements(payload #> '{course,chapters}') as chapter(value)
  cross join lateral jsonb_to_recordset(chapter.value->'lessons') as lesson(id text, "itemIds" text[]) cross join lateral unnest(lesson."itemIds") with ordinality as item(item_id, sort_order) on conflict do nothing;
end $michi_seed$;


-- Supabase parity for the authored practical errands expansion.
