ry":"places","difficulty":1,"prerequisiteIds":[],"tags":["places","movement"],"character":"出","meanings":["exit","go out"],"onyomi":["シュツ","スイ"],"kunyomi":["でる","だす"],"usefulWords":[{"word":"出口","reading":"でぐち","meaning":"exit"},{"word":"出る","reading":"でる","meaning":"to leave"}]},{"id":"kanji-kuchi","slug":"kuchi","title":"口","jlptLevel":"N5","category":"kanji","subcategory":"places","difficulty":1,"prerequisiteIds":[],"tags":["places","body"],"character":"口","meanings":["mouth","opening"],"onyomi":["コウ","ク"],"kunyomi":["くち"],"usefulWords":[{"word":"入口","reading":"いりぐち","meaning":"entrance"},{"word":"出口","reading":"でぐち","meaning":"exit"}]},{"id":"kanji-juu","slug":"juu","title":"住","jlptLevel":"N5","category":"kanji","subcategory":"home","difficulty":2,"prerequisiteIds":[],"tags":["home","places"],"character":"住","meanings":["live","reside"],"onyomi":["ジュウ"],"kunyomi":["すむ"],"usefulWords":[{"word":"住む","reading":"すむ","meaning":"to live"},{"word":"住所","reading":"じゅうしょ","meaning":"address"}]},{"id":"kanji-sho","slug":"sho-place","title":"所","jlptLevel":"N5","category":"kanji","subcategory":"places","difficulty":2,"prerequisiteIds":[],"tags":["places","home"],"character":"所","meanings":["place"],"onyomi":["ショ"],"kunyomi":["ところ"],"usefulWords":[{"word":"住所","reading":"じゅうしょ","meaning":"address"},{"word":"場所","reading":"ばしょ","meaning":"place"}]},{"id":"kanji-motsu","slug":"motsu","title":"持","jlptLevel":"N5","category":"kanji","subcategory":"daily life","difficulty":2,"prerequisiteIds":[],"tags":["daily life","travel"],"character":"持","meanings":["hold","carry"],"onyomi":["ジ"],"kunyomi":["もつ"],"usefulWords":[{"word":"持つ","reading":"もつ","meaning":"to carry"},{"word":"気持ち","reading":"きもち","meaning":"feeling"}]},{"id":"kanji-iro","slug":"iro","title":"色","jlptLevel":"N5","category":"kanji","subcategory":"description","difficulty":1,"prerequisiteIds":[],"tags":["description","shopping"],"character":"色","meanings":["color"],"onyomi":["ショク","シキ"],"kunyomi":["いろ"],"usefulWords":[{"word":"色","reading":"いろ","meaning":"color"},{"word":"何色","reading":"なにいろ","meaning":"what color"}]},{"id":"kanji-aka","slug":"aka","title":"赤","jlptLevel":"N5","category":"kanji","subcategory":"description","difficulty":1,"prerequisiteIds":[],"tags":["description","shopping"],"character":"赤","meanings":["red"],"onyomi":["セキ","シャク"],"kunyomi":["あかい"],"usefulWords":[{"word":"赤い","reading":"あかい","meaning":"red"},{"word":"赤ちゃん","reading":"あかちゃん","meaning":"baby"}]},{"id":"kanji-kuro","slug":"kuro","title":"黒","jlptLevel":"N5","category":"kanji","subcategory":"description","difficulty":1,"prerequisiteIds":[],"tags":["description","shopping"],"character":"黒","meanings":["black"],"onyomi":["コク"],"kunyomi":["くろい"],"usefulWords":[{"word":"黒い","reading":"くろい","meaning":"black"},{"word":"黒板","reading":"こくばん","meaning":"blackboard"}]},{"id":"kanji-sakana","slug":"sakana","title":"魚","jlptLevel":"N5","category":"kanji","subcategory":"food","difficulty":2,"prerequisiteIds":[],"tags":["food","shopping"],"character":"魚","meanings":["fish"],"onyomi":["ギョ"],"kunyomi":["さかな","うお"],"usefulWords":[{"word":"魚","reading":"さかな","meaning":"fish"},{"word":"魚料理","reading":"さかなりょうり","meaning":"fish dish"}]},{"id":"kanji-sai","slug":"sai","title":"菜","jlptLevel":"N5","category":"kanji","subcategory":"food","difficulty":2,"prerequisiteIds":[],"tags":["food","shopping"],"character":"菜","meanings":["vegetable","greens"],"onyomi":["サイ"],"kunyomi":[],"usefulWords":[{"word":"野菜","reading":"やさい","meaning":"vegetables"},{"word":"菜食","reading":"さいしょく","meaning":"vegetarian food"}]},{"id":"kanji-noru","slug":"noru","title":"乗","jlptLevel":"N5","category":"kanji","subcategory":"transport","difficulty":2,"prerequisiteIds":[],"tags":["transport","movement"],"character":"乗","meanings":["ride","board"],"onyomi":["ジョウ"],"kunyomi":["のる","のせる"],"usefulWords":[{"word":"乗る","reading":"のる","meaning":"to ride"},{"word":"乗り物","reading":"のりもの","meaning":"vehicle"}]}],"grammar":[{"id":"grammar-na-adjective","slug":"na-adjective","title":"な-adjectives","jlptLevel":"N5","category":"grammar","subcategory":"adjective forms","difficulty":2,"prerequisiteIds":["grammar-desu"],"tags":["adjective","description"],"pattern":"な-adjective + です","meaning":"describe a person, place, or thing with a な-adjective","formation":"な-adjective + です; before a noun, keep な: 便利な店","intuition":"な-adjectives connect to です as a complete description, and keep な when they directly modify a noun.","usageConditions":["Use です after the adjective at the end of a polite sentence.","Keep な before a noun: 便利な店, not 便利店."],"examples":[{"japanese":"この店は便利です。","translation":"This shop is convenient."},{"japanese":"便利な駅の近くに住んでいます。","translation":"I live near a convenient station."}],"commonMistakes":["Do not add い to make a な-adjective: 便利です, not 便利いです.","Use な before a noun, but not before です."],"contrastIds":["contrast-adjective-forms"],"practiceQuestionIds":[]},{"id":"grammar-i-adjective-negative","slug":"i-adjective-negative","title":"い-adjective negative","jlptLevel":"N5","category":"grammar","subcategory":"adjective forms","difficulty":2,"prerequisiteIds":["grammar-i-adjective"],"tags":["adjective","negative","description"],"pattern":"いAくないです","meaning":"is not い-adjective","formation":"Replace final い with くないです: 近い → 近くないです","intuition":"The adjective changes shape before the negative ending; the old final い does not stay.","usageConditions":["Use it to politely say something is not a quality.","いい is irregular: いい → よくないです."],"examples":[{"japanese":"駅は遠くないです。","translation":"The station is not far."},{"japanese":"この料理は熱くないです。","translation":"This dish is not hot."}],"commonMistakes":["Do not say 遠いじゃないです for a beginner い-adjective pattern; use 遠くないです.","Change い to く before ない."],"contrastIds":["contrast-adjective-forms"],"practiceQuestionIds":[]},{"id":"grammar-i-adjective-past","slug":"i-adjective-past","title":"い-adjective past","jlptLevel":"N5","category":"grammar","subcategory":"adjective forms","difficulty":2,"prerequisiteIds":["grammar-i-adjective"],"tags":["adjective","past","description"],"pattern":"いAかったです","meaning":"was い-adjective","formation":"Replace final い with かったです: 暑い → 暑かったです","intuition":"かった marks the adjective as a past description.","usageConditions":["Use it for a polite past description.","いい is irregular: いい → よかったです."],"examples":[{"japanese":"昨日は暑かったです。","translation":"Yesterday was hot."},{"japanese":"旅行は楽しかったです。","translation":"The trip was fun."}],"commonMistakes":["Do not keep い before かった: 暑かった, not 暑いかった.","Remember the irregular form よかったです for いい."],"contrastIds":["contrast-adjective-forms"],"practiceQuestionIds":[]},{"id":"grammar-teiru","slug":"te-iru","title":"ています","jlptLevel":"N5","category":"grammar","subcategory":"verb forms","difficulty":3,"prerequisiteIds":["grammar-te-form"],"tags":["verb","ongoing","routine"],"pattern":"Vています","meaning":"be doing V; be in a state resulting from V","formation":"Verb て-form + います","intuition":"ています keeps attention on an action in progress or a state that continues now.","usageConditions":["Use it for an action happening now: 食べています.","Some verbs describe an ongoing state: 住んでいます means live/reside."],"examples":[{"japanese":"今、料理をしています。","translation":"I am cooking now."},{"japanese":"東京に住んでいます。","translation":"I live in Tokyo."}],"commonMistakes":["Use the て-form before います, not the dictionary form.","Do not assume every ています sentence means the speaker is doing it at this exact second."],"contrastIds":["contrast-teiru-simple"],"practiceQuestionIds":[]},{"id":"grammar-tewaikenai","slug":"tewaikenai","title":"てはいけません","jlptLevel":"N5","category":"grammar","subcategory":"permission","difficulty":3,"prerequisiteIds":["grammar-te-form"],"tags":["permission","prohibition","rules"],"pattern":"Vてはいけません","meaning":"must not V; V is not allowed","formation":"Verb て-form + はいけません","intuition":"This pattern marks an action as outside the allowed boundary.","usageConditions":["Use it for rules and clear prohibitions.","The softer question てもいいですか asks for permission instead."],"examples":[{"japanese":"ここで写真を撮ってはいけません。","translation":"You must not take photos here."},{"japanese":"この部屋に入ってはいけません。","translation":"You must not enter this room."}],"commonMistakes":["Use て-form before はいけません.","It means prohibition, not a request for permission."],"contrastIds":["contrast-permission-prohibition"],"practiceQuestionIds":[]},{"id":"grammar-naidekudasai","slug":"naidekudasai","title":"ないでください","jlptLevel":"N5","category":"grammar","subcategory":"requests","difficulty":3,"prerequisiteIds":["grammar-te-kudasai"],"tags":["request","prohibition","conversation"],"pattern":"Vないでください","meaning":"please do not V","formation":"Negative verb + でください","intuition":"This is a polite request asking someone to leave an action undone.","usageConditions":["Use it for a personal polite request.","Use てはいけません when stating a stronger rule or prohibition."],"examples":[{"japanese":"ここで話さないでください。","translation":"Please do not talk here."},{"japanese":"荷物を置かないでください。","translation":"Please do not put luggage here."}],"commonMistakes":["Do not attach ください directly to the dictionary form.","Keep the negative ない before でください."],"contrastIds":["contrast-permission-prohibition"],"practiceQuestionIds":[]},{"id":"grammar-nai-form","slug":"nai-form","title":"ない form","jlptLevel":"N5","category":"grammar","subcategory":"verb forms","difficulty":3,"prerequisiteIds":["grammar-dictionary-form"],"tags":["verb","negative"],"pattern":"Vない","meaning":"not V; negative plain form","formation":"Godan verbs change to the あ-row + ない; ichidan verbs drop る + ない","intuition":"ない makes the verb negative in a plain form that can connect to other patterns.","usageConditions":["Use it before でください and other patterns that require the negative form.","する becomes しない and 来る becomes 来ない."],"examples":[{"japanese":"今日は学校へ行かない。","translation":"I am not going to school today."},{"japanese":"魚を食べない人もいます。","translation":"There are also people who do not eat fish."}],"commonMistakes":["For godan verbs, use the あ-row: 書く → 書かない.","行く is irregular in this form: 行かない."],"contrastIds":[],"practiceQuestionIds":[]}],"grammarContrasts":[{"id":"contrast-adjective-forms","title":"Adjective forms across time","grammarPointIds":["grammar-i-adjective","grammar-i-adjective-negative","grammar-i-adjective-past","grammar-na-adjective"],"explanation":"い-adjectives change their ending for negative and past meanings, while な-adjectives connect with です and keep な before a noun.","examples":[{"japanese":"駅は近いです。","translation":"The station is near."},{"japanese":"駅は遠くなかったです。","translation":"The station was not far."}],"exercises":["Change an い-adjective to its polite negative form.","Choose な before a noun, but not before です."]},{"id":"contrast-permission-prohibition","title":"てもいい and てはいけません","grammarPointIds":["grammar-temoii","grammar-tewaikenai","grammar-naidekudasai"],"explanation":"てもいいです asks or grants permission. てはいけません states that an action is not allowed, while ないでください makes a polite personal request not to do it.","examples":[{"japanese":"ここで写真を撮ってもいいですか。","translation":"May I take photos here?"},{"japanese":"ここで写真を撮ってはいけません。","translation":"You must not take photos here."}],"exercises":["Ask whether an action is permitted with てもいいですか.","State a clear rule with てはいけません."]},{"id":"contrast-teiru-simple","title":"ています and simple present","grammarPointIds":["grammar-teiru","grammar-masu"],"explanation":"ます describes a routine or general action, while ています focuses on an action in progress or a continuing state.","examples":[{"japanese":"毎日、料理をします。","translation":"I cook every day."},{"japanese":"今、料理をしています。","translation":"I am cooking now."}],"exercises":["Use ます for a regular routine.","Use ています for what is happening now."]}],"readings":[{"id":"reading-shopping-list","slug":"shopping-list","title":"買い物メモ","jlptLevel":"N5","category":"reading","subcategory":"practical information","difficulty":3,"prerequisiteIds":["grammar-kudasai","grammar-na-adjective"],"tags":["shopping","food","information"],"passage":"今日の買い物\n朝ご飯のパンと、魚と野菜を買います。黒いかばんも必要です。店は駅の近くです。","translation":"Today's shopping: I will buy bread for breakfast, fish, and vegetables. A black bag is also needed. The shop is near the station.","vocabularyIds":["vocab-asagohan","vocab-sakana","vocab-yasai","vocab-kuroi","vocab-benri","vocab-hitsuyou","vocab-chikaku","vocab-eki"],"grammarIds":["grammar-masu","grammar-na-adjective"],"kanjiIds":["kanji-asa","kanji-sakana","kanji-sai","kanji-kuro","kanji-chika"],"estimatedDifficulty":3,"questions":[{"prompt":"何を買いますか。","options":["魚と野菜","切符と本","水と傘","服と靴"],"correctAnswer":0,"questionType":"information retrieval","explanation":"メモ says 魚と野菜を買います, along with bread and a bag."},{"prompt":"店はどこですか。","options":["大学の中","駅の近く","家の右","学校の外"],"correctAnswer":1,"questionType":"short passage detail","explanation":"店は駅の近くです。"}]},{"id":"reading-station-sign","slug":"station-sign","title":"駅の案内","jlptLevel":"N5","category":"reading","subcategory":"practical information","difficulty":3,"prerequisiteIds":["grammar-te-kudasai","grammar-imasu"],"tags":["transport","directions","information"],"passage":"駅の入口は左です。切符を買って、まっすぐ行ってください。電車は二番線です。出口は右にあります。","translation":"The station entrance is on the left. Buy a ticket and go straight. The train is on platform 2. The exit is on the right.","vocabularyIds":["vocab-eki","vocab-iriguchi","vocab-kippu","vocab-massugu","vocab-migi","vocab-hidari","vocab-deguchi"],"grammarIds":["grammar-te-form","grammar-te-kudasai","grammar-imasu"],"kanjiIds":["kanji-iri","kanji-kiri","kanji-migi","kanji-hidari","kanji-de"],"estimatedDifficulty":3,"questions":[{"prompt":"入口はどちらですか。","options":["右","左","まっすぐ","二番線"],"correctAnswer":1,"questionType":"short passage detail","explanation":"駅の入口は左です。"},{"prompt":"切符を買ったあと、どうしますか。","options":["右へ曲がります","家へ帰ります","まっすぐ行きます","店で注文します"],"correctAnswer":2,"questionType":"task-based response","explanation":"切符を買って、まっすぐ行ってください。"}]}],"listening":[{"id":"listening-restaurant-order","slug":"restaurant-order","title":"レストランで注文","jlptLevel":"N5","category":"listening","subcategory":"practical request","difficulty":3,"prerequisiteIds":["grammar-kudasai","vocab-chuumon"],"tags":["food","shopping","request"],"situation":"A customer orders a simple meal and asks for the bill.","audioUrl":null,"voice":"ja-JP conversational TTS","speed":0.84,"sourceType":"tts","transcript":"店員：いらっしゃいませ。\n客：魚料理をお願いします。\n店員：はい。飲み物はいかがですか。\n客：水をください。\n店員：かしこまりました。","questions":[{"prompt":"客は何を注文しますか。","answers":["魚料理","野菜だけ","切符","朝ご飯のパン"],"correctAnswer":0,"questionType":"key point","explanation":"魚料理をお願いします。"},{"prompt":"客は何をくださいと言いますか。","answers":["お茶","水","料理","切符"],"correctAnswer":1,"questionType":"verbal expression","explanation":"客 says 水をください。"}]},{"id":"listening-station-directions","slug":"station-directions","title":"駅までの道","jlptLevel":"N5","category":"listening","subcategory":"directions","difficulty":3,"prerequisiteIds":["grammar-te-kudasai","vocab-massugu"],"tags":["transport","directions","places"],"situation":"A visitor asks how to get to the station.","audioUrl":null,"voice":"ja-JP conversational TTS","speed":0.84,"sourceType":"tts","transcript":"A：すみません。駅はどこですか。\nB：この道をまっすぐ行って、右へ曲がってください。\nA：駅は近いですか。\nB：はい、近いです。入口は左にあります。","questions":[{"prompt":"駅へ行くとき、最初にどうしますか。","answers":["左へ曲がります","まっすぐ行きます","切符を買います","店に入ります"],"correctAnswer":1,"questionType":"task-based response","explanation":"この道をまっすぐ行ってください。"},{"prompt":"入口はどちらにありますか。","answers":["右","左","駅の中","遠い所"],"correctAnswer":1,"questionType":"key point","explanation":"入口は左にあります。"}]}]}$michi_practical_payload$::jsonb;
begin
  select id, 'course-n5-foundations', slug, title, description, region, 4
  from jsonb_to_recordset(payload #> '{course,chapters}') as chapter(id text, slug text, title text, description text, region text) on conflict (id) do nothing;
  select lesson.id, 'chapter-practical-errands', lesson.slug, lesson.title, lesson.subtitle, lesson.description, lesson."estimatedMinutes", 0
  from jsonb_array_elements(payload #> '{course,chapters}') as chapter(value)
  cross join lateral jsonb_to_recordset(chapter.value->'lessons') as lesson(id text, slug text, title text, subtitle text, description text, "estimatedMinutes" integer) on conflict (id) do nothing;
  select item.id, item.slug, item.category, item."jlptLevel", item.subcategory, item.difficulty, item."prerequisiteIds", item.tags
  from jsonb_to_recordset((payload->'vocabulary') || (payload->'kanji') || (payload->'grammar') || (payload->'readings') || (payload->'listening')) as item(id text, slug text, category text, subcategory text, difficulty integer, "jlptLevel" text, "prerequisiteIds" text[], tags text[]) on conflict (id) do nothing;
  select item.id, item."writtenForm", item.reading, item.meanings, item."partOfSpeech", item.commonness, item."exampleSentences", item.collocations, item."relatedWords", item.antonyms, item.notes
  from jsonb_to_recordset(payload->'vocabulary') as item(id text, "writtenForm" text, reading text, meanings text[], "partOfSpeech" text, commonness integer, "exampleSentences" jsonb, collocations text[], "relatedWords" text[], antonyms text[], notes text) on conflict (item_id) do nothing;
  select item.id, item.character, item.meanings, item.onyomi, item.kunyomi, item."usefulWords"
  from jsonb_to_recordset(payload->'kanji') as item(id text, character text, meanings text[], onyomi text[], kunyomi text[], "usefulWords" jsonb) on conflict (item_id) do nothing;
  select item.id, item.pattern, item.meaning, item.formation, item.intuition, item."usageConditions", item.examples, item."commonMistakes", item."contrastIds", item."practiceQuestionIds"
  from jsonb_to_recordset(payload->'grammar') as item(id text, pattern text, meaning text, formation text, intuition text, "usageConditions" text[], examples jsonb, "commonMistakes" text[], "contrastIds" text[], "practiceQuestionIds" text[]) on conflict (item_id) do nothing;
  select item.id, item.title, item."grammarPointIds", item.explanation, item.examples, item.exercises
  from jsonb_to_recordset(payload->'grammarContrasts') as item(id text, title text, "grammarPointIds" text[], explanation text, examples jsonb, exercises text[]) on conflict (id) do nothing;
  select item.id, item.title, item.passage, item.translation, item."vocabularyIds", item."grammarIds", item."kanjiIds", item."estimatedDifficulty"
  from jsonb_to_recordset(payload->'readings') as item(id text, title text, passage text, translation text, "vocabularyIds" text[], "grammarIds" text[], "kanjiIds" text[], "estimatedDifficulty" integer) on conflict (item_id) do nothing;
  select item.id, item.title, item.situation, item."audioUrl", item.voice, item.speed, item."sourceType", item.transcript, item.questions
  from jsonb_to_recordset(payload->'listening') as item(id text, title text, situation text, "audioUrl" text, voice text, speed numeric, "sourceType" text, transcript text, questions jsonb) on conflict (item_id) do nothing;
  select lesson.id, item.item_id, item.sort_order::integer
  from jsonb_array_elements(payload #> '{course,chapters}') as chapter(value)
  cross join lateral jsonb_to_recordset(chapter.value->'lessons') as lesson(id text, "itemIds" text[])
  cross join lateral unnest(lesson."itemIds") with ordinality as item(item_id, sort_order) on conflict do nothing;
end $michi_practical$;

