values
  ('chapter-first-steps', 'course-n5-foundations', 'first-steps', 'First steps', 'Introduce yourself, name familiar things, and ask simple questions.', 'quiet-city', 0),
  ('chapter-daily-life', 'course-n5-foundations', 'daily-life', 'Daily life', 'Move from naming things to describing simple routines.', 'train-line', 1),
  ('chapter-everyday-world', 'course-n5-foundations', 'everyday-world', 'Everyday world', 'Point things out, describe places, and ask for simple directions.', 'small-town', 2)
insert into public.lessons (id, chapter_id, slug, title, subtitle, description, estimated_minutes, sort_order)
values
  ('lesson-meeting-people', 'chapter-first-steps', 'meeting-people', 'Meeting people', 'はじめまして', 'Build a small introduction you can actually use.', 12, 0),
  ('lesson-morning-route', 'chapter-first-steps', 'morning-route', 'The morning route', '朝の道', 'Talk about time, places, transport, and what you do each day.', 14, 1),
  ('lesson-food-and-routines', 'chapter-daily-life', 'food-and-routines', 'Food and routines', '毎日のこと', 'Use polite verbs and familiar words to describe your day.', 15, 0),
  ('lesson-weather-and-shopping', 'chapter-daily-life', 'weather-and-shopping', 'Weather and small errands', '雨の日', 'Talk about the weather, say what you want, and handle a simple purchase.', 16, 1),
  ('lesson-home-and-directions', 'chapter-everyday-world', 'home-and-directions', 'Home and directions', '部屋と道', 'Use object, location, and possession patterns to describe the world around you.', 18, 0),
  ('lesson-plans-and-descriptions', 'chapter-everyday-world', 'plans-and-descriptions', 'Plans and descriptions', '週末の予定', 'Describe things, connect actions, and say what you want to do next.', 20, 1)
