insert into public.vocabulary (item_id, written_form, reading, meanings, part_of_speech, commonness, example_sentences, collocations, related_words, antonyms, notes)
values
  ('vocab-watashi','私','わたし',array['I','me'],'pronoun',5,'[{"japanese":"私は学生です。","translation":"I am a student."}]','{"私の名前","私は〜です"}',array['あなた'],'{}','In ordinary polite conversation, 私 is a safe default for I.'),
  ('vocab-gakusei','学生','がくせい',array['student'],'noun',5,'[{"japanese":"大学の学生です。","translation":"I am a university student."}]','{"大学生","学生です"}',array['先生'],'{}','学生 is a general word for student.'),
  ('vocab-sensei','先生','せんせい',array['teacher','instructor'],'noun',5,'[{"japanese":"先生は親切です。","translation":"The teacher is kind."}]','{"大学の先生","先生に聞く"}',array['学生'],'{}','先生 is used for a teacher and some other respected professionals.'),
  ('vocab-daigaku','大学','だいがく',array['university','college'],'noun',5,'[{"japanese":"大学へ行きます。","translation":"I go to university."}]','{"大学生","大学で勉強する"}',array['学校'],'{}','大学 can mean the institution or its campus.'),
  ('vocab-tomodachi','友達','ともだち',array['friend'],'noun',5,'[{"japanese":"友達と駅へ行きます。","translation":"I go to the station with a friend."}]','{"友達と話す","友達の家"}',array['友人'],'{}','と marks the person you do something with.'),
  ('vocab-kazoku','家族','かぞく',array['family'],'noun',5,'[{"japanese":"家族は四人です。","translation":"There are four people in my family."}]','{"家族と住む","家族の写真"}',array['父','母'],'{}','Use people counters when saying how many people are in a family.'),
  ('vocab-mainichi','毎日','まいにち',array['every day'],'adverb',5,'[{"japanese":"毎日、日本語を勉強します。","translation":"I study Japanese every day."}]','{"毎日起きる","毎日学校へ行く"}',array['毎朝'],'{}','Recurring time words usually do not need に.'),
  ('vocab-asa','朝','あさ',array['morning'],'noun',5,'[{"japanese":"朝、コーヒーを飲みます。","translation":"I drink coffee in the morning."}]','{"朝ご飯","朝早く"}',array['昼','夜'],'{}','朝 can set the time without に.'),
  ('vocab-eki','駅','えき',array['station'],'noun',5,'[{"japanese":"駅で友達を待ちます。","translation":"I wait for a friend at the station."}]','{"駅に着く","駅の前"}',array['電車'],'{}','で marks where the action happens.'),
  ('vocab-densha','電車','でんしゃ',array['train'],'noun',5,'[{"japanese":"電車で大学へ行きます。","translation":"I go to university by train."}]','{"電車に乗る","電車を待つ"}',array['駅'],'{}','で can mark the means of transport.'),
  ('vocab-ie','家','いえ',array['house','home'],'noun',5,'[{"japanese":"家で本を読みます。","translation":"I read a book at home."}]','{"家に帰る","家の近く"}',array['部屋'],'{}','家 can mean a building or home.'),
  ('vocab-gakko','学校','がっこう',array['school'],'noun',5,'[{"japanese":"学校は駅の近くです。","translation":"The school is near the station."}]','{"学校へ行く","学校の先生"}',array['大学'],'{}','The small っ in がっこう creates a brief pause.'),
  ('vocab-hon','本','ほん',array['book'],'noun',5,'[{"japanese":"この本は新しいです。","translation":"This book is new."}]','{"本を読む","日本語の本"}',array['辞書'],'{}','This lesson uses 本 in its book meaning.'),
  ('vocab-mizu','水','みず',array['water'],'noun',5,'[{"japanese":"水を飲みます。","translation":"I drink water."}]','{"水を買う","冷たい水"}',array['お茶'],'{}','お水 is a polite service expression.'),
  ('vocab-gohan','ご飯','ごはん',array['meal','cooked rice'],'noun',5,'[{"japanese":"朝ご飯を食べます。","translation":"I eat breakfast."}]','{"朝ご飯","ご飯を作る"}',array['食べる'],'{}','ご飯 often means a meal in daily speech.'),
  ('vocab-taberu','食べる','たべる',array['to eat'],'ichidan verb',5,'[{"japanese":"毎朝、パンを食べます。","translation":"I eat bread every morning."}]','{"ご飯を食べる","一緒に食べる"}',array['飲む'],'{}','The polite form introduced here is 食べます.'),
  ('vocab-nomu','飲む','のむ',array['to drink'],'godan verb',5,'[{"japanese":"駅で水を飲みます。","translation":"I drink water at the station."}]','{"水を飲む","薬を飲む"}',array['食べる'],'{}','飲む is a godan verb; its polite form is 飲みます.'),
  ('vocab-iku','行く','いく',array['to go'],'godan verb',5,'[{"japanese":"明日、大学へ行きます。","translation":"I will go to university tomorrow."}]','{"学校へ行く","一緒に行く"}',array['来る','帰る'],'{}','へ highlights direction; に can also mark a destination.'),
  ('vocab-kuru','来る','くる',array['to come'],'irregular verb',5,'[{"japanese":"友達が家に来ます。","translation":"A friend comes to my home."}]','{"家に来る","日本に来る"}',array['行く'],'{}','来ます is pronounced きます.'),
  ('vocab-miru','見る','みる',array['to see','to watch','to look at'],'ichidan verb',5,'[{"japanese":"夜、テレビを見ます。","translation":"I watch television at night."}]','{"映画を見る","写真を見る"}',array['読む'],'{}','Context decides the best English translation.'),
  ('vocab-benkyou','勉強する','べんきょうする',array['to study'],'する verb',5,'[{"japanese":"毎日、日本語を勉強します。","translation":"I study Japanese every day."}]','{"大学で勉強する","一時間勉強する"}',array['学校'],'{}','する turns 勉強 into the verb to study.'),
  ('vocab-kau','買う','かう',array['to buy'],'godan verb',5,'[{"japanese":"駅で本を買います。","translation":"I buy a book at the station."}]','{"本を買う","飲み物を買う"}',array['売る'],'{}','買う becomes 買います in polite present form.'),
  ('vocab-ookii','大きい','おおきい',array['big','large'],'い-adjective',5,'[{"japanese":"大きい駅です。","translation":"It is a large station."}]','{"大きい町","とても大きい"}',array['小さい'],array['小さい'],'大きい directly modifies nouns.'),
  ('vocab-atarashii','新しい','あたらしい',array['new'],'い-adjective',5,'[{"japanese":"新しい本を買います。","translation":"I buy a new book."}]','{"新しい学校","新しい友達"}',array['古い'],array['古い'],'The い remains before a noun.' ),
  ('vocab-kyou','今日','きょう',array['today'],'noun',5,'[{"japanese":"今日は学校へ行きます。","translation":"I am going to school today."}]','{"今日の予定","今日は〜です"}',array['明日','昨日'],array[]::text[],'今日 is commonly read きょう in everyday speech.'),
  ('vocab-ashita','明日','あした',array['tomorrow'],'noun',5,'[{"japanese":"明日、大学へ行きます。","translation":"I will go to university tomorrow."}]','{"明日の朝","明日の予定"}',array['今日','昨日'],array[]::text[],'明日 is a time word and usually does not need に.'),
  ('vocab-getsuyoubi','月曜日','げつようび',array['Monday'],'noun',5,'[{"japanese":"月曜日に日本語を勉強します。","translation":"I study Japanese on Monday."}]','{"月曜日の朝","月曜日から"}',array['日曜日'],array[]::text[],'曜日 names end in 曜日; the first kanji identifies the day.'),
  ('vocab-tenki','天気','てんき',array['weather'],'noun',5,'[{"japanese":"今日の天気はいいです。","translation":"Today’s weather is good."}]','{"天気予報","いい天気"}',array['雨','晴れ'],array[]::text[],'天気 is often paired with いい or 悪い when describing conditions.'),
  ('vocab-ame','雨','あめ',array['rain'],'noun',5,'[{"japanese":"今日は雨です。","translation":"It is raining today."}]','{"雨の日","雨が降る"}',array['天気','雪'],array['晴れ'],'The noun 雨 can be used with です for a simple weather statement.'),
  ('vocab-kasa','傘','かさ',array['umbrella'],'noun',5,'[{"japanese":"雨の日は傘を使います。","translation":"I use an umbrella on rainy days."}]','{"傘を持つ","傘を買う"}',array['雨'],array[]::text[],'傘 is a practical object for weather conversations and errands.'),
  ('vocab-konbini','コンビニ','こんびに',array['convenience store'],'noun',5,'[{"japanese":"コンビニで水を買います。","translation":"I buy water at a convenience store."}]','{"コンビニへ行く","コンビニで買う"}',array['店'],array[]::text[],'コンビニ is a common everyday loanword written in katakana.'),
  ('vocab-ikura','いくら','いくら',array['how much'],'疑問詞',5,'[{"japanese":"これはいくらですか。","translation":"How much is this?"}]','{"いくらですか","いくらありますか"}',array['円'],array[]::text[],'いくら asks about an amount or price.'),
  ('vocab-en','円','えん',array['yen'],'counter / noun',5,'[{"japanese":"これは五百円です。","translation":"This is 500 yen."}]','{"百円","円です"}',array['いくら'],array[]::text[],'円 follows a number when stating a price in yen.'),
  ('vocab-yasui','安い','やすい',array['cheap','inexpensive'],'い-adjective',5,'[{"japanese":"この傘は安いです。","translation":"This umbrella is inexpensive."}]','{"安い店","とても安い"}',array['高い'],array['高い'],'安い describes a low price.'),
  ('vocab-suki','好き','すき',array['liked','fond of'],'な-adjective',5,'[{"japanese":"私は日本語が好きです。","translation":"I like Japanese."}]','{"音楽が好き","好きな食べ物"}',array['嫌い'],array['嫌い'],'好き normally takes が for the thing that is liked.'),
  ('vocab-hoshii','欲しい','ほしい',array['wanted','desired'],'い-adjective',5,'[{"japanese":"新しい傘が欲しいです。","translation":"I want a new umbrella."}]','{"水が欲しい","何が欲しいですか"}',array['好き'],array[]::text[],'欲しい describes wanting an object.' ),
  ('vocab-kore','これ','これ',array['this','this one'],'pronoun',5,'[{"japanese":"これは私の本です。","translation":"This is my book."}]','{"これは何ですか","これをください"}',array['それ','あれ'],array[]::text[],'これ refers to something near the speaker.'),
  ('vocab-sore','それ','それ',array['that','that one'],'pronoun',5,'[{"japanese":"それは先生の机です。","translation":"That is the teacher''s desk."}]','{"それは何ですか","それを見ます"}',array['これ','あれ'],array[]::text[],'それ refers to something near the listener or already mentioned.'),
  ('vocab-doko','どこ','どこ',array['where'],'疑問詞',5,'[{"japanese":"駅はどこですか。","translation":"Where is the station?"}]','{"どこですか","どこへ行きますか"}',array['ここ','そこ'],array[]::text[],'どこ asks about a place.'),
  ('vocab-heya','部屋','へや',array['room'],'noun',5,'[{"japanese":"部屋に机があります。","translation":"There is a desk in the room."}]','{"部屋の中","私の部屋"}',array['家','机'],array[]::text[],'部屋 is a room inside a building.'),
  ('vocab-isu','椅子','いす',array['chair'],'noun',5,'[{"japanese":"机の前に椅子があります。","translation":"There is a chair in front of the desk."}]','{"椅子に座る","椅子の前"}',array['机'],array[]::text[],'椅子 is commonly paired with 座る, to sit.'),
  ('vocab-tsukue','机','つくえ',array['desk','table'],'noun',5,'[{"japanese":"机の上に本があります。","translation":"There is a book on the desk."}]','{"机の上","机の前"}',array['椅子','本'],array[]::text[],'机 usually means a desk or study table.'),
  ('vocab-mise','店','みせ',array['shop','store'],'noun',5,'[{"japanese":"店で傘を買います。","translation":"I buy an umbrella at the shop."}]','{"店へ行く","店の前"}',array['コンビニ'],array[]::text[],'店 is the general word for a shop or store.'),
  ('vocab-mae','前','まえ',array['front','before'],'noun',5,'[{"japanese":"駅の前で会います。","translation":"I meet in front of the station."}]','{"駅の前","食事の前"}',array['後ろ','上'],array['後ろ'],'前 can describe physical position or an earlier time.'),
  ('vocab-ue','上','うえ',array['above','on','up'],'noun',5,'[{"japanese":"机の上に本があります。","translation":"There is a book on the desk."}]','{"机の上","上にあります"}',array['下','中'],array['下'],'上 describes a higher position.'),
  ('vocab-shita','下','した',array['under','below','down'],'noun',5,'[{"japanese":"机の下に椅子があります。","translation":"There is a chair under the desk."}]','{"机の下","下にあります"}',array['上','中'],array['上'],'下 describes a lower position.'),
  ('vocab-naka','中','なか',array['inside','middle'],'noun',5,'[{"japanese":"部屋の中に机があります。","translation":"There is a desk inside the room."}]','{"部屋の中","箱の中"}',array['上','下'],array[]::text[],'中 means inside or middle depending on context.'),
  ('vocab-kaisha','会社','かいしゃ',array['company','office'],'noun',5,'[{"japanese":"会社は駅の前です。","translation":"The company is in front of the station."}]','{"会社へ行く","会社の人"}',array['大学','駅'],array[]::text[],'会社 can refer to a company or its office.'),
  ('vocab-hanasu','話す','はなす',array['to speak','to talk'],'godan verb',5,'[{"japanese":"友達と日本語を話します。","translation":"I speak Japanese with a friend."}]','{"日本語を話す","友達と話す"}',array['聞く','言う'],array[]::text[],'話す is a godan verb; its polite form is 話します.')
insert into public.vocabulary (item_id, written_form, reading, meanings, part_of_speech, commonness, example_sentences, collocations, related_words, antonyms, notes)
values
  ('vocab-shuumatsu','週末','しゅうまつ',array['weekend'],'noun',5,'[{"japanese":"週末に友達と会います。","translation":"I meet a friend on the weekend."}]','{"週末の予定","週末に行く"}',array['毎日','月曜日'],array[]::text[],'週末 refers to the end of the week, usually Saturday and Sunday.'),
  ('vocab-basu','バス','ばす',array['bus'],'noun',5,'[{"japanese":"バスで学校へ行きます。","translation":"I go to school by bus."}]','{"バスに乗る","バスで行く"}',array['電車','駅'],array[]::text[],'で marks the means of transport in バスで行きます.'),
  ('vocab-jikan','時間','じかん',array['time','hours'],'noun',5,'[{"japanese":"時間があります。","translation":"I have time."}]','{"一時間","時間がある"}',array['今','毎日'],array[]::text[],'時間 can mean an amount of time or available time depending on context.'),
  ('vocab-toshokan','図書館','としょかん',array['library'],'noun',5,'[{"japanese":"図書館で本を読みます。","translation":"I read a book at the library."}]','{"図書館へ行く","図書館で勉強する"}',array['大学','本'],array[]::text[],'図書館 is a useful study and public-information location.'),
  ('vocab-samui','寒い','さむい',array['cold'],'い-adjective',5,'[{"japanese":"今日は寒いです。","translation":"It is cold today."}]','{"寒い日","とても寒い"}',array['暑い','天気'],array['暑い'],'寒い describes cold weather or surroundings; 冷たい is used for cold things to the touch.'),
  ('vocab-hayai','早い','はやい',array['early'],'い-adjective',5,'[{"japanese":"今日は早いです。","translation":"It is early today."}]','{"早い時間","朝早い"}',array['遅い'],array['遅い'],'This course uses 早い for early; 速い is the similar-sounding word for fast.'),
  ('vocab-kantan','簡単','かんたん',array['easy','simple'],'な-adjective',5,'[{"japanese":"これは簡単な本です。","translation":"This is an easy book."}]','{"簡単です","簡単な問題"}',array['難しい'],array['難しい'],'Use 簡単な before a noun and 簡単です at the end of a polite sentence.'),
  ('vocab-omoshiroi','面白い','おもしろい',array['interesting','funny'],'い-adjective',5,'[{"japanese":"この本は面白いです。","translation":"This book is interesting."}]','{"面白い本","とても面白い"}',array['楽しい','本'],array['つまらない'],'面白い can mean interesting or funny; context supplies the nuance.'),
  ('vocab-takai','高い','たかい',array['expensive','high'],'い-adjective',5,'[{"japanese":"この本は高いです。","translation":"This book is expensive."}]','{"高い店","とても高い"}',array['安い'],array['安い'],'高い can describe price or physical height; context decides which meaning fits.')
insert into public.kanji (item_id, character, meanings, onyomi, kunyomi, useful_words)
values
  ('kanji-watashi','私',array['I','private'],array['シ'],array['わたし','わたくし'],'[{"word":"私","reading":"わたし","meaning":"I"}]'),
  ('kanji-gaku','学',array['study','learning'],array['ガク'],array['まなぶ'],'[{"word":"学生","reading":"がくせい","meaning":"student"},{"word":"大学","reading":"だいがく","meaning":"university"},{"word":"学校","reading":"がっこう","meaning":"school"}]'),
  ('kanji-sen','先',array['before','ahead'],array['セン'],array['さき'],'[{"word":"先生","reading":"せんせい","meaning":"teacher"},{"word":"先週","reading":"せんしゅう","meaning":"last week"}]'),
  ('kanji-hi','日',array['day','sun'],array['ニチ','ジツ'],array['ひ','か'],'[{"word":"毎日","reading":"まいにち","meaning":"every day"},{"word":"日本","reading":"にほん","meaning":"Japan"}]'),
  ('kanji-dai','大',array['big','large'],array['ダイ','タイ'],array['おおきい'],'[{"word":"大学","reading":"だいがく","meaning":"university"},{"word":"大きい","reading":"おおきい","meaning":"big"}]'),
  ('kanji-shou','小',array['small'],array['ショウ'],array['ちいさい','こ','お'],'[{"word":"小さい","reading":"ちいさい","meaning":"small"}]'),
  ('kanji-shoku','食',array['eat','food'],array['ショク','ジキ'],array['たべる','くう'],'[{"word":"食べる","reading":"たべる","meaning":"to eat"},{"word":"食事","reading":"しょくじ","meaning":"meal"}]'),
  ('kanji-ima','今',array['now','present'],array['コン','キン'],array['いま'],'[{"word":"今","reading":"いま","meaning":"now"},{"word":"今日","reading":"きょう","meaning":"today"}]'),
  ('kanji-tsuki','月',array['month','moon'],array['ゲツ','ガツ'],array['つき'],'[{"word":"月曜日","reading":"げつようび","meaning":"Monday"},{"word":"月","reading":"つき","meaning":"moon"}]'),
  ('kanji-ame','雨',array['rain'],array['ウ'],array['あめ','あま-','-さめ'],'[{"word":"雨","reading":"あめ","meaning":"rain"},{"word":"雨の日","reading":"あめのひ","meaning":"rainy day"}]'),
  ('kanji-go','五',array['five'],array['ゴ'],array['いつつ'],'[{"word":"五つ","reading":"いつつ","meaning":"five things"},{"word":"五百円","reading":"ごひゃくえん","meaning":"500 yen"}]'),
  ('kanji-en','円',array['yen','circle'],array['エン'],array[]::text[],'[{"word":"円","reading":"えん","meaning":"yen"},{"word":"百円","reading":"ひゃくえん","meaning":"100 yen"}]'),
  ('kanji-yasu','安',array['cheap','safe'],array['アン'],array['やすい','やすむ'],'[{"word":"安い","reading":"やすい","meaning":"cheap"},{"word":"安全","reading":"あんぜん","meaning":"safe"}]'),
  ('kanji-ue','上',array['above','up'],array['ジョウ','ショウ'],array['うえ','あがる','あげる'],'[{"word":"上","reading":"うえ","meaning":"above"},{"word":"上手","reading":"じょうず","meaning":"skillful"}]'),
  ('kanji-shita','下',array['below','down'],array['カ','ゲ'],array['した','さがる','さげる'],'[{"word":"下","reading":"した","meaning":"below"},{"word":"地下","reading":"ちか","meaning":"underground"}]'),
  ('kanji-mae','前',array['front','before'],array['ゼン'],array['まえ'],'[{"word":"前","reading":"まえ","meaning":"front / before"},{"word":"名前","reading":"なまえ","meaning":"name"}]'),
  ('kanji-naka','中',array['inside','middle'],array['チュウ','ジュウ'],array['なか'],'[{"word":"中","reading":"なか","meaning":"inside"},{"word":"中国","reading":"ちゅうごく","meaning":"China"}]'),
  ('kanji-ka','会',array['meet','meeting'],array['カイ','エ'],array['あう'],'[{"word":"会う","reading":"あう","meaning":"to meet"},{"word":"会社","reading":"かいしゃ","meaning":"company"}]'),
  ('kanji-han','話',array['talk','story'],array['ワ'],array['はなす','はなし'],'[{"word":"話す","reading":"はなす","meaning":"to speak"},{"word":"話","reading":"はなし","meaning":"story / talk"}]')
insert into public.kanji (item_id, character, meanings, onyomi, kunyomi, useful_words)
values
  ('kanji-shuu','週',array['week'],array['シュウ'],array[]::text[],'[{"word":"週末","reading":"しゅうまつ","meaning":"weekend"},{"word":"毎週","reading":"まいしゅう","meaning":"every week"}]'),
  ('kanji-ji','時',array['time','hour'],array['ジ'],array['とき'],'[{"word":"時間","reading":"じかん","meaning":"time / hours"},{"word":"何時","reading":"なんじ","meaning":"what time"}]'),
  ('kanji-kan','間',array['interval','between'],array['カン','ケン'],array['あいだ','ま'],'[{"word":"時間","reading":"じかん","meaning":"time / hours"},{"word":"間","reading":"あいだ","meaning":"between / interval"}]'),
  ('kanji-haya','早',array['early'],array['ソウ','サッ'],array['はやい','はやまる','はやめる'],'[{"word":"早い","reading":"はやい","meaning":"early"},{"word":"早く","reading":"はやく","meaning":"early / quickly"}]'),
  ('kanji-kyuu','休',array['rest','holiday'],array['キュウ'],array['やすむ','やすみ'],'[{"word":"休む","reading":"やすむ","meaning":"to rest"},{"word":"休み","reading":"やすみ","meaning":"holiday / break"}]')
insert into public.grammar_points (item_id, pattern, meaning, formation, intuition, usage_conditions, examples, common_mistakes, contrast_ids, practice_question_ids)
values
  ('grammar-desu','Noun は Noun です','to state what something is','Noun + は + Noun/adjective + です','です closes a polite statement.','{"Use it for polite present statements.","It can follow a noun or adjective predicate."}','[{"japanese":"私は学生です。","translation":"I am a student."},{"japanese":"これは新しい本です。","translation":"This is a new book."}]','{"Do not add です after a polite verb such as 行きます.","は is pronounced wa as a particle."}',array['contrast-wa-ga'],array['grammar-q-desu-1']),
  ('grammar-wa','Topic は comment','as for X','Noun + は + information about that noun','は puts a small spotlight on the thing you want the rest of the sentence to describe.','{"Use it to establish or contrast a topic.","It does not always mark the grammatical subject."}','[{"japanese":"私は大学生です。","translation":"As for me, I am a university student."},{"japanese":"この本は新しいです。","translation":"This book is new."}]','{"Do not read は as ha when it is a particle.","Do not treat は as a universal translation for is."}',array['contrast-wa-ga'],array['grammar-q-wa-1']),
  ('grammar-ka','Statement か','turns a polite statement into a question','Polite sentence + か','か at the end opens the sentence for an answer without changing word order.','{"Use it at the end of a polite question.","A rising voice is optional in careful speech."}','[{"japanese":"学生ですか。","translation":"Are you a student?"},{"japanese":"これは本ですか。","translation":"Is this a book?"}]','{"Do not add English-style do/does words.","Keep the polite ending before か."}',array[]::text[],array['grammar-q-ka-1']),
  ('grammar-ni','Place/time に verb','marks a destination, specific time, or existence location','Destination/time + に + movement or time-sensitive predicate','に marks a point the action is aimed at or anchored to.','{"Use it for a destination with 行く, 来る, and 帰る.","Use it for a clock time or specific date.","Use で for the place where an action happens."}','[{"japanese":"大学に行きます。","translation":"I go to university."},{"japanese":"七時に起きます。","translation":"I wake up at seven."}]','{"駅に待ちます is wrong for waiting at a station.","毎日 usually does not take に."}',array['contrast-ni-de'],array['grammar-q-ni-1']),
  ('grammar-masu','Verb stem + ます','polite non-past action or habit','Remove the dictionary-form ending and add the polite stem ending.','ます gives an action a respectful, everyday conversational finish.','{"Use it for present habits and future actions.","Its negative is ません and past is ました."}','[{"japanese":"毎日、本を読みます。","translation":"I read books every day."},{"japanese":"明日、駅へ行きます。","translation":"I will go to the station tomorrow."}]','{"食べるます is wrong; use 食べます.","来ます is pronounced きます."}',array[]::text[],array['grammar-q-masu-1']),
  ('grammar-masen','Verb stem + ません','polite non-past negative','Replace ます with ません: 食べません, 行きません.','ません keeps the polite tone while turning an action off.','{"Use it for things you do not do or will not do.","The time comes from context, just like with ます."}','[{"japanese":"今日は学校へ行きません。","translation":"I am not going to school today."},{"japanese":"肉を食べません。","translation":"I do not eat meat."}]','{"Do not use ないです in this polite verb pattern.","Keep the verb stem before ません."}',array['contrast-masu-tense'],array[]::text[]),
  ('grammar-mashita','Verb stem + ました','polite past action','Replace ます with ました: 食べました, 行きました.','ました closes a polite action that is already finished.','{"Use it for completed actions in the past.","A time word such as 昨日 or 先週 makes the time clear."}','[{"japanese":"昨日、本を読みました。","translation":"I read a book yesterday."},{"japanese":"友達と大学へ行きました。","translation":"I went to university with a friend."}]','{"Do not use ます for a finished action when the time is clearly past.","The negative past form comes later."}',array['contrast-masu-tense'],array[]::text[]),
  ('grammar-suki','N が 好きです','to like or be fond of N','Thing liked + が + 好きです.','好き describes a positive feeling toward something; が points to what receives that feeling.','{"Use が for the thing you like in a simple preference statement.","Use 嫌いです for a dislike."}','[{"japanese":"私は日本語が好きです。","translation":"I like Japanese."},{"japanese":"友達は音楽が好きです。","translation":"My friend likes music."}]','{"Do not automatically use を with 好き.","好き is a な-adjective."}',array['contrast-suki-hoshii'],array[]::text[]),
  ('grammar-hoshii','N が 欲しいです','to want N','Desired thing + が + 欲しいです.','欲しい describes a desire for an object, not an action.','{"Use が for the thing you want.","Use 〜たい for wanting to do an action; that pattern comes later."}','[{"japanese":"新しい傘が欲しいです。","translation":"I want a new umbrella."},{"japanese":"何が欲しいですか。","translation":"What do you want?"}]','{"Do not use を for the object wanted in this basic pattern.","欲しい is an adjective."}',array['contrast-suki-hoshii'],array[]::text[]),
  ('grammar-kudasai','N を ください','please give me N','Requested item + を + ください.','ください turns a named item into a polite, practical request.','{"Use it when asking for an item in a shop or service setting.","Add ですか when you want to make the request a question."}','[{"japanese":"水をください。","translation":"Water, please."},{"japanese":"メニューをください。","translation":"The menu, please."}]','{"The requested item takes を in this pattern.","ください is already polite."}',array[]::text[],array[]::text[]),
  ('grammar-arimasu','Place に thing があります','there is a non-living thing at a place','Place + に + thing + が + あります.','に marks where something exists, while が introduces the thing that is there.','{"Use あります for objects and places.","Use います for people and animals; that contrast comes next."}','[{"japanese":"机の上に本があります。","translation":"There is a book on the desk."},{"japanese":"駅にコンビニがあります。","translation":"There is a convenience store at the station."}]','{"Do not use で for the location of existence.","Do not use あります for a person or animal."}',array[]::text[],array[]::text[]),
  ('grammar-wo','N を verb','marks the direct object of an action','Object + を + transitive verb','を points to the thing receiving the action.','{"Use it with actions such as 食べる, 飲む, 読む, and 買う.","The particle を is pronounced o."}','[{"japanese":"本を読みます。","translation":"I read a book."},{"japanese":"水を買います。","translation":"I buy water."}]','{"Do not use は when the sentence needs a direct object.","Read を as o, not wo, in modern pronunciation."}',array['contrast-wo-de'],array[]::text[]),
  ('grammar-de','Place / means で verb','marks where an action happens or what is used to do it','Place or means + で + action','で frames the setting or tool of an action.','{"Use it for the place where an action happens.","Use it for a means of transport or tool."}','[{"japanese":"家で勉強します。","translation":"I study at home."},{"japanese":"電車で大学へ行きます。","translation":"I go to university by train."}]','{"Use に for a destination, not the place where an action happens.","Use あります with に for existence, not で."}',array['contrast-wo-de','contrast-ni-de'],array[]::text[]),
  ('grammar-to','Person と verb','with a person or together with','Person + と + shared action','と links the person who shares the action with you.','{"Use it when doing something together with someone.","It can also join nouns in a complete list."}','[{"japanese":"友達と話します。","translation":"I talk with a friend."},{"japanese":"家族と大学へ行きます。","translation":"I go to university with my family."}]','{"Do not use で for the person you do an action with.","と is different from も, which means also."}',array[]::text[],array[]::text[]),
  ('grammar-no','N の N','connects a possessor, category, or description to a noun','Related noun + の + main noun','の ties two nouns together so the second one is understood through the first.','{"Use it for possession, such as 私の本.","Use it for categories or relationships, such as 大学の先生."}','[{"japanese":"これは私の本です。","translation":"This is my book."},{"japanese":"駅の前に店があります。","translation":"There is a shop in front of the station."}]','{"The main noun comes after の.","Do not translate every の as English of."}',array['contrast-no-mo'],array[]::text[]),
  ('grammar-mo','N も','also or too','N + も + the same predicate','も adds another item to an already established statement.','{"Use it when the new subject or object shares the same information.","も often replaces は, が, or を in simple sentences."}','[{"japanese":"友達もこの本を見ます。","translation":"My friend also looks at this book."},{"japanese":"私も学生です。","translation":"I am a student too."}]','{"Do not stack も with は in this basic pattern.","The repeated information can remain understood."}',array['contrast-no-mo'],array[]::text[]),
  ('grammar-kore','これ / それ / あれ は N です','identifies an object by its distance from the speaker and listener','これ, それ, or あれ + は + noun + です','The demonstrative chooses the viewpoint before you name the thing.','{"Use これ for something near the speaker.","Use それ for something near the listener or just mentioned; use あれ for something far from both."}','[{"japanese":"これは新しい本です。","translation":"This is a new book."},{"japanese":"それは先生の机です。","translation":"That is the teacher''s desk."}]','{"Use この, その, and あの directly before a noun.","Do not use これ本; これ stands alone."}',array['contrast-kore-doko'],array[]::text[]),
  ('grammar-doko','N は どこですか','asks where something or someone is','Topic + は + どこですか','どこ leaves the place slot open for the listener to fill.','{"Use it to ask for a location.","Use どこへ or どこに with movement verbs when asking about a destination."}','[{"japanese":"駅はどこですか。","translation":"Where is the station?"},{"japanese":"どこで話しますか。","translation":"Where will we talk?"}]','{"Use どこ for places, not 何 for things.","Keep the question particle か in a polite question."}',array['contrast-kore-doko'],array[]::text[]),
  ('grammar-imasu','Place に person が います','there is a person or animal at a place','Place + に + living thing + が + います','います gives a living presence a place in the scene.','{"Use it for people and animals.","Use あります for objects and places."}','[{"japanese":"部屋に友達がいます。","translation":"There is a friend in the room."},{"japanese":"学校に先生がいます。","translation":"There is a teacher at school."}]','{"Do not use あります for a person or animal.","The place takes に in an existence sentence."}',array['contrast-arimasu-imasu'],array[]::text[])
insert into public.grammar_points (item_id, pattern, meaning, formation, intuition, usage_conditions, examples, common_mistakes, contrast_ids, practice_question_ids)
values
  ('grammar-i-adjective','い-adjective です / くないです / かったです','describes qualities in present and past forms','Keep い for non-past; change い to くない for negative and かった for past.','The adjective ending carries the time and polarity of the description.','{"Use い-adjectives directly before nouns.","For polite predicates, use です after the adjective form."}','[{"japanese":"今日は寒いです。","translation":"It is cold today."},{"japanese":"昨日は寒くなかったです。","translation":"It was not cold yesterday."}]','{"Do not add な after an い-adjective before a noun: 寒い日.","Do not say 寒いくない; change い to くない."}',array['contrast-adjective-forms'],array[]::text[]),
  ('grammar-dictionary-form','Verb dictionary form','the plain non-past form used in basic references and casual statements','Use the dictionary form such as 食べる, 行く, or 話す.','The dictionary form is the compact base form from which many patterns grow.','{"Use it in dictionaries and casual speech.","Use it before some grammar patterns, including たい and こと."}','[{"japanese":"毎日、本を読む。","translation":"I read books every day."},{"japanese":"週末に図書館へ行く。","translation":"I go to the library on weekends."}]','{"Do not attach です directly to a plain verb: 行くです.","Do not confuse a dictionary form with the polite ます form."}',array['contrast-dictionary-masu'],array[]::text[]),
  ('grammar-te-form','Vて、V','connects actions in sequence or a related description','Use a verb''s て-form before the next action; common forms include 読んで and 起きて.','て-form leaves the sentence open so the next action can follow naturally.','{"Use it to show actions happening in sequence.","It also appears in permission, prohibition, and requests; those patterns are introduced separately."}','[{"japanese":"本を読んで、勉強します。","translation":"I read a book and then study."},{"japanese":"朝起きて、水を飲みます。","translation":"I wake up in the morning and drink water."}]','{"Do not use the dictionary form to connect these actions in this pattern.","The て-form of 飲む is 飲んで, not 飲て."}',array['contrast-te-tai'],array[]::text[]),
  ('grammar-tai','Verb stem + たいです','wants to do an action','Replace ます with たいです: 行きたいです, 読みたいです.','たい turns an action into a personal wish or plan.','{"Use it for wanting to do something.","Use 欲しい for wanting an object."}','[{"japanese":"日本語を勉強したいです。","translation":"I want to study Japanese."},{"japanese":"週末に本を読みたいです。","translation":"I want to read a book on the weekend."}]','{"Use たい for an action, not for an object you want to own.","Keep the object particle を before the action: 本を読みたいです."}',array['contrast-te-tai'],array[]::text[]),
  ('grammar-counters','Number + counter','counts people and objects with an appropriate counter','Place the counter after the number: 三冊 for three books, 二人 for two people.','Japanese counts different kinds of things with small category labels.','{"Use 冊 for bound books and 二人 for two people.","Counter readings can change with certain numbers, so learn useful chunks in context."}','[{"japanese":"本を三冊買いました。","translation":"I bought three books."},{"japanese":"友達が二人います。","translation":"I have two friends."}]','{"Do not leave a counted noun without a counter in these basic patterns.","Learn the counter reading as a whole phrase rather than translating number by number."}',array[]::text[],array[]::text[]),
  ('grammar-yori','A は B より adjective です','compares A with B','A + は + B + より + adjective + です','より sets the reference point for the comparison.','{"Use it when saying one thing is more or less a quality than another.","The adjective describes the first item, A."}','[{"japanese":"電車はバスより大きいです。","translation":"The train is bigger than the bus."},{"japanese":"この本はあの本より面白いです。","translation":"This book is more interesting than that book."}]','{"Put the reference item before より.","Do not use と to make this basic comparison."}',array[]::text[],array[]::text[]),
  ('grammar-kara','Reason から, result','because or so','State the reason + から, then the result or decision.','から lets the listener know why the next statement follows.','{"Use it to give a simple reason for an action or condition.","In beginner polite speech, place から after the polite statement."}','[{"japanese":"雨ですから、家にいます。","translation":"Because it is raining, I will stay home."},{"japanese":"時間がありますから、勉強します。","translation":"Because I have time, I will study."}]','{"The reason comes before から in these examples.","Do not confuse the reason marker から with the starting-point meaning of から."}',array[]::text[],array[]::text[]),
  ('grammar-temoii','Vてもいいですか','asks for permission to do something','Verb て-form + もいいですか','もいいですか checks whether an action is acceptable.','{"Use it politely before doing an action.","A positive answer can be いいですよ; a refusal may use いけません."}','[{"japanese":"ここで話してもいいですか。","translation":"May I talk here?"},{"japanese":"この本を見てもいいですか。","translation":"May I look at this book?"}]','{"Keep も in the pattern: 話してもいいですか.","Use the て-form before もいい, not the dictionary form."}',array[]::text[],array[]::text[])
insert into public.grammar_contrasts (id, title, grammar_point_ids, explanation, examples, exercises)
values
  ('contrast-wa-ga','は and が',array['grammar-wa','grammar-desu'],'Use は to introduce the topic. が more narrowly identifies the subject or answers who/what is involved.','[{"japanese":"私は学生です。","translation":"As for me, I am a student."},{"japanese":"誰が学生ですか。私が学生です。","translation":"Who is a student? I am the student."}]','{"Choose は when setting a topic.","Choose が when answering who or what."}'),
  ('contrast-ni-de','に and で',array['grammar-ni'],'に marks a destination or point in time. で marks the place or means where an action happens.','[{"japanese":"駅に行きます。","translation":"I go to the station."},{"japanese":"駅で電車を待ちます。","translation":"I wait for the train at the station."}]','{"大学___行きます。","家___勉強します。"}'),
  ('contrast-masu-tense','ます, ません, and ました',array['grammar-masu','grammar-masen','grammar-mashita'],'The stem stays the same while the ending tells the listener whether the polite action is non-past, negative, or finished in the past.','[{"japanese":"毎日、本を読みます。","translation":"I read a book every day."},{"japanese":"昨日、本を読みました。","translation":"I read a book yesterday."}]','{"Change the action to a polite negative: 飲みます → 飲みません。","Choose the finished action: 行きます or 行きました。"}'),
  ('contrast-suki-hoshii','好き and 欲しい',array['grammar-suki','grammar-hoshii'],'好き describes a positive feeling toward something. 欲しい describes wanting to have an object. Both commonly use が, but they answer different questions.','[{"japanese":"日本語が好きです。","translation":"I like Japanese."},{"japanese":"新しい本が欲しいです。","translation":"I want a new book."}]','{"Use 好き for a preference and 欲しい for a desired object.","Ask what someone wants: 何が欲しいですか。"}'),
  ('contrast-wo-de','を and で',array['grammar-wo','grammar-de'],'を marks the thing receiving an action. で marks where the action happens or the means used to do it.','[{"japanese":"本を読みます。","translation":"I read a book."},{"japanese":"家で読みます。","translation":"I read at home."}]','{"Choose を for the object: 水___飲みます。","Choose で for the setting: 部屋___勉強します。"}'),
  ('contrast-no-mo','の and も',array['grammar-no','grammar-mo'],'の connects nouns. も adds another noun to the same statement as also or too.','[{"japanese":"私の本です。","translation":"It is my book."},{"japanese":"友達も学生です。","translation":"My friend is also a student."}]','{"Connect the nouns: 大学___先生。","Add also: 私___学生です。"}'),
  ('contrast-kore-doko','これ and どこ',array['grammar-kore','grammar-doko'],'これ identifies a nearby object. どこ asks for a place. They both help you navigate a simple conversation without a long description.','[{"japanese":"これは何ですか。","translation":"What is this?"},{"japanese":"駅はどこですか。","translation":"Where is the station?"}]','{"Use これ when pointing at an object.","Use どこ when asking for a location."}'),
  ('contrast-arimasu-imasu','あります and います',array['grammar-arimasu','grammar-imasu'],'あります describes non-living things. います describes people and animals. Both use に for the place where something exists.','[{"japanese":"机があります。","translation":"There is a desk."},{"japanese":"友達がいます。","translation":"There is a friend."}]','{"Use あります for an object.","Use います for a person or animal."}')
insert into public.grammar_contrasts (id, title, grammar_point_ids, explanation, examples, exercises)
values
  ('contrast-adjective-forms','い-adjective forms',array['grammar-i-adjective'],'い-adjectives change their ending to express a negative or past description, while keeping the adjective meaning visible.','[{"japanese":"今日は寒いです。","translation":"It is cold today."},{"japanese":"昨日は寒くなかったです。","translation":"It was not cold yesterday."}]','{"Change 寒い to its negative form: 寒くないです。","Choose the past form: 面白かったです。"}'),
  ('contrast-dictionary-masu','Dictionary form and ます form',array['grammar-dictionary-form','grammar-masu'],'The dictionary form is a plain base form. The ます form expresses the same action in a polite register.','[{"japanese":"本を読む。","translation":"I read a book. (plain)"},{"japanese":"本を読みます。","translation":"I read a book. (polite)"}]','{"Match 読む with its polite form 読みます.","Do not attach です directly to 行く."}'),
  ('contrast-te-tai','て-form and たい',array['grammar-te-form','grammar-tai'],'て-form connects an action to what follows. たい changes an action into a desire, so the two forms do different jobs.','[{"japanese":"本を読んで、勉強します。","translation":"I read a book and then study."},{"japanese":"本を読みたいです。","translation":"I want to read a book."}]','{"Use て-form to connect two actions.","Use たい to say you want to do an action."}')
