  ('vocab-shukudai', '宿題', 'しゅくだい', array['homework'], 'noun', 5, '[{"japanese":"宿題をします。","translation":"I do homework."}]'::jsonb, array['宿題をする','宿題が終わる'], array['学校','勉強'], array[]::text[], null),
