insert into public.grammar_points (item_id, pattern, meaning, formation, intuition, usage_conditions, examples, common_mistakes, contrast_ids, practice_question_ids)
values
  ('grammar-ta-form', 'Vた', 'plain past; did V', 'Change the final sound using the same pattern family as て-form, then use た or だ.', 'た closes a plain statement about an action that is already finished.', array['Use it in casual statements and before grammar that needs a plain past clause.','Use だ after the same verb groups that take で in the て-form.'], '[{"japanese":"昨日、映画を見た。","translation":"I watched a movie yesterday."},{"japanese":"本を読んだあとで、寝ました。","translation":"After reading a book, I went to sleep."}]'::jsonb, array['Do not use the polite ending ました inside a plain-past pattern.','Learn the た-form with its て-form family.'], array['contrast-ta-masu','contrast-mae-ato'], array['grammar-ta-form-meaning','grammar-ta-form-completion','grammar-ta-form-order']),
  ('grammar-mae-ni', 'Vる前に', 'before doing V', 'Dictionary-form verb + 前に; noun + の前に.', '前に puts one action before a later action on the timeline.', array['Use the dictionary form before 前に for an action that has not happened yet.','Use の after a noun.'], '[{"japanese":"寝る前に、本を読みます。","translation":"Before going to bed, I read a book."},{"japanese":"学校へ行く前に、朝ご飯を食べます。","translation":"Before going to school, I eat breakfast."}]'::jsonb, array['Use the dictionary form before 前に, not the polite ます form.','Do not confuse 前に with あとで.'], array['contrast-mae-ato'], array['grammar-mae-ni-meaning','grammar-mae-ni-completion','grammar-mae-ni-order']),
  ('grammar-ato-de', 'Vたあとで', 'after doing V; later', 'Plain past verb + あとで; noun + のあとで.', 'あとで starts with a finished action and then points to what follows it.', array['Use the plain past form before あとで for a completed action.','Use の after a noun.'], '[{"japanese":"ご飯を食べたあとで、勉強します。","translation":"After eating, I study."},{"japanese":"映画を見たあとで、友達と話します。","translation":"After watching a movie, I talk with a friend."}]'::jsonb, array['Use た-form before あとで, not dictionary form.','The action before あとで happens first.'], array['contrast-mae-ato'], array['grammar-ato-de-meaning','grammar-ato-de-completion','grammar-ato-de-order']),
  ('grammar-toki', 'Vとき / Aとき', 'when; at the time that', 'Plain form + とき; noun + のとき.', 'とき frames the time or situation in which the main action happens.', array['Use a plain verb, adjective, or noun phrase before とき.','Match the form to the time you mean.'], '[{"japanese":"寒いときは、家にいます。","translation":"When it is cold, I stay home."},{"japanese":"日本へ行ったとき、写真を撮りました。","translation":"When I went to Japan, I took photos."}]'::jsonb, array['Do not force every とき clause into the past.','Use のとき after a noun.'], array['contrast-toki-nagara'], array['grammar-toki-meaning','grammar-toki-completion','grammar-toki-order']),
  ('grammar-nagara', 'Vながら', 'while doing V', 'Verb stem + ながら; the second action is the main action.', 'ながら keeps two actions in the same scene, with the second action as the focus.', array['Use the verb stem before ながら.','The same person normally does both actions.'], '[{"japanese":"音楽を聞きながら、勉強します。","translation":"I study while listening to music."},{"japanese":"歩きながら、友達と話します。","translation":"I talk with a friend while walking."}]'::jsonb, array['Remove ます from the polite form before adding ながら.','The action after ながら is usually the main action.'], array['contrast-toki-nagara'], array['grammar-nagara-meaning','grammar-nagara-completion','grammar-nagara-order'])
insert into public.grammar_contrasts (id, title, grammar_point_ids, explanation, examples, exercises)
values
  ('contrast-ta-masu', 'た form and ます form', array['grammar-ta-form','grammar-masu'], 'The ます form is polite and non-past. The plain た form describes a finished action and can connect to later grammar.', '[{"japanese":"映画を見ます。","translation":"I watch a movie."},{"japanese":"映画を見た。","translation":"I watched a movie."}]'::jsonb, array['Choose the polite form for a conversation with a teacher.','Use the plain past form before あとで.']),
  ('contrast-mae-ato', '前に and あとで', array['grammar-mae-ni','grammar-ato-de'], '前に places an action before a reference action. あとで places an action after a completed action.', '[{"japanese":"寝る前に、本を読みます。","translation":"I read a book before sleeping."},{"japanese":"本を読んだあとで、寝ます。","translation":"After reading a book, I sleep."}]'::jsonb, array['Put a routine before bedtime with 前に.','Describe what happens after dinner with あとで.']),
  ('contrast-toki-nagara', 'とき and ながら', array['grammar-toki','grammar-nagara'], 'とき frames when a situation happens. ながら joins two actions happening at the same time, with the later action as the main focus.', '[{"japanese":"寒いときは、家にいます。","translation":"When it is cold, I stay home."},{"japanese":"音楽を聞きながら、勉強します。","translation":"I study while listening to music."}]'::jsonb, array['Frame a weather-based routine with とき.','Join two simultaneous actions with ながら.'])
insert into public.readings (item_id, title, passage, translation, vocabulary_ids, grammar_ids, kanji_ids, estimated_difficulty)
values
  ('reading-school-and-health', '学校のあとで', '今日は学校へ行きました。教室で宿題をして、先生に質問しました。答えを聞いたあとで、頭が痛かったです。午後、病院へ行きました。医者に薬の話を聞いて、家で薬を飲みました。体を休めました。', 'Today I went to school. I did homework in the classroom and asked the teacher a question. After hearing the answer, my head hurt. In the afternoon, I went to the hospital. I heard about medicine from the doctor, took medicine at home, and rested my body.', array['vocab-kyou','vocab-gakko','vocab-kyoushitsu','vocab-shukudai','vocab-sensei','vocab-shitsumon','vocab-kotae','vocab-kiku','vocab-atama','vocab-itai','vocab-gogo','vocab-byouin','vocab-isha','vocab-kusuri','vocab-nomu','vocab-karada','vocab-yasumu'], array['grammar-wa','grammar-te-form','grammar-ta-form','grammar-ato-de','grammar-i-adjective-past','grammar-masu'], array['kanji-gaku','kanji-kyou','kanji-shitsu','kanji-shuku','kanji-shitsumon','kanji-mon','kanji-kotae','kanji-atama','kanji-byou','kanji-byoin','kanji-i','kanji-kusuri','kanji-tai'], 4),
  ('reading-seasons-and-plans', '一年の予定', '去年の春は晴れでした。夏は暑いです。家で音楽を聞いたあとで、映画を見ました。今年の秋は、音楽を聞きながら日本語を勉強する予定です。冬は雪が好きですが、寒いときは家にいます。来月の予定はまだ分かりません。', 'Last spring was sunny. Summer is hot. At home, after listening to music, I watched a movie. This autumn, I plan to study Japanese while listening to music. I like snow in winter, but when it is cold, I stay home. I do not know next month plans yet.', array['vocab-kyonen','vocab-haru','vocab-hare','vocab-natsu','vocab-atsui','vocab-ie','vocab-ongaku','vocab-kiku','vocab-eiga','vocab-miru','vocab-kotoshi','vocab-aki','vocab-benkyou','vocab-yotei','vocab-fuyu','vocab-yuki','vocab-samui','vocab-raigetsu','vocab-wakaru'], array['grammar-ta-form','grammar-ato-de','grammar-toki','grammar-nagara','grammar-tai','grammar-masu'], array['kanji-kyou','kanji-haru','kanji-hare','kanji-natsu','kanji-on','kanji-raku','kanji-ei','kanji-ga','kanji-aki','kanji-fuyu','kanji-yuki'], 4)
