values
  ('listening-health-appointment', '病院の予約', 'A learner explains a symptom and arranges a hospital visit.', null, 'ja-JP conversational TTS', 0.82, 'tts', E'A：頭が痛いです。病院へ行きたいです。\nB：予約がありますか。\nA：いいえ、ありません。\nB：では、午後二時に来てください。', '[{"prompt":"Aさんはどこが痛いですか。","answers":["頭","体","足","手"],"correctAnswer":0,"questionType":"key point","explanation":"頭が痛いです。"},{"prompt":"Aさんは予約がありますか。","answers":["はい、あります","いいえ、ありません","午後二時です","病院です"],"correctAnswer":1,"questionType":"quick response","explanation":"いいえ、ありません。"},{"prompt":"何時に来てくださいと言われましたか。","answers":["午前二時","午後一時","午後二時","午後五時"],"correctAnswer":2,"questionType":"information retrieval","explanation":"午後二時に来てください。"}]'::jsonb),
  ('listening-weekend-weather', '季節の予定', 'Two friends talk about activities for different seasons and weather.', null, 'ja-JP conversational TTS', 0.82, 'tts', E'A：来月の予定はありますか。\nB：はい。今年の夏は映画を見たいです。\nA：秋は何をしますか。\nB：音楽を聞きながら勉強します。\nA：冬はどうですか。\nB：雪の日は家にいます。', '[{"prompt":"今年の夏、何をしたいですか。","answers":["映画を見たいです","音楽を聞きたいです","病院へ行きたいです","学校で勉強したいです"],"correctAnswer":0,"questionType":"key point","explanation":"今年の夏は映画を見たいです。"},{"prompt":"秋はどうやって勉強しますか。","answers":["映画を見ながら","音楽を聞きながら","歩きながら","食べながら"],"correctAnswer":1,"questionType":"task-based response","explanation":"音楽を聞きながら勉強します。"},{"prompt":"雪の日はどうしますか。","answers":["学校へ行きます","駅で友達に会います","家にいます","病院へ行きます"],"correctAnswer":2,"questionType":"quick response","explanation":"雪の日は家にいます。"}]'::jsonb)
